import sys,json,pathlib,traceback
sys.path.insert(0,'/opt/tools')
import numpy as np
from rcb_client import Robot
from PIL import Image
OUT=pathlib.Path('/app/output'); OUT.mkdir(exist_ok=True)
r=Robot(); spec=r.spec()
(OUT/'spec.json').write_text(json.dumps(spec,indent=2))
obs=None; seq=0

def save(res,label):
 global obs,seq
 obs=res; seq+=1
 path=OUT/f'{seq:03d}_{label}'; res.save(str(path))
 for cam,arr in res.last.items():
  Image.fromarray(arr).save(OUT/f'{cam}.png')
  if cam in res.last_depth: np.save(OUT/f'{cam}_depth.npy',res.last_depth[cam])
 (OUT/'latest_meta.json').write_text(json.dumps(res.meta,indent=2))
 print(json.dumps({'saved':str(path),'done':res.meta.get('done'),'reason':res.meta.get('reason'),'plan':res.meta.get('plan'),'proprio':res.meta.get('proprio'),'time_left_s':res.meta.get('time_left_s')}),flush=True)

save(r.get_obs(depth=True),'initial')
print('READY',flush=True)
for line in sys.stdin:
 try:
  cmd=json.loads(line)
  (OUT/'commands.jsonl').open('a').write(json.dumps(cmd)+'\n')
  if cmd['op']=='obs': save(r.get_obs(depth=True,seconds=cmd.get('seconds',0)),cmd.get('label','obs'))
  elif cmd['op']=='status': print(r.status(),flush=True)
  elif cmd['op']=='ik': print(json.dumps(r.ik(cmd['targets'],seed=np.r_[obs.group('joint_position',now=True)[:7],obs.group('joint_position',now=True)[8:15]].tolist(),**cmd.get('opts',{}))),flush=True)
  elif cmd['op']=='exec': exec(cmd['code'])
  elif cmd['op']=='submit': save(r.submit(cmd.get('type','ee_pose'),cmd['actions'],dt=cmd.get('dt',0.1),video='mp4',depth=True,note=cmd.get('label','')),cmd.get('label','move'))
 except Exception:
  traceback.print_exc()
 print('READY',flush=True)
